package com.idfc.ai.runbook.confluence; import java.util.regex.*; import org.springframework.stereotype.Component;
@Component public class ManualNotesService { static final String START="<!-- MANUAL SUPPORT NOTES START -->",END="<!-- MANUAL SUPPORT NOTES END -->"; public String extract(String body){Matcher m=Pattern.compile(Pattern.quote(START)+"(.*?)"+Pattern.quote(END),Pattern.DOTALL).matcher(body);if(!m.find())throw new IllegalArgumentException("RUNBOOK_MANUAL_MARKERS_MISSING");return m.group(1);} public String combine(String generated,String notes){return generated.replace(START+"<p>Not Applicable</p>"+END,START+notes+END);} }
